const S=require('./subjects.cjs'),seeds=require('./guided-seeds.json');
const thermal=require('./question-bank.json').cards,other=require('./course-bank.json').cards;
const visuals=[...require('./visual-bank.json').cards.map(c=>({...c,subject:'termicas'})),...require('./course-visual-bank.json').cards];
function source(r){if(r.url)return r;const match=r.id.match(/^(BI|BII)-(\d+)$/);return {...r,url:match?`https://drive.google.com/file/d/${match[1]==='BI'?'1bQt9DS_V2dEgTa2SbswRXeJSXOc3-ed7':'1eK0ar8DqgNc-jdxkMpxSqck99HfkB_DU'}/view#page=${match[2]}`:r.id.startsWith('turbinas-')?'https://docs.google.com/document/d/12jYZ1yKDaT50KlPs9JprAmgbbh_D7ZuN/edit':null}}
function lesson(subject,unit){const config=S.get(subject),seed=seeds[subject]?.[unit];if(!config||!seed||!Number.isInteger(unit))return null;const cards=(subject==='termicas'?thermal:other.filter(c=>c.subject===subject)).filter(c=>c.unit===unit);const diagrams=visuals.filter(c=>c.subject===subject&&c.unit===unit);
 const sections=[{id:'idea',label:'1. Comprender',title:seed.title,paragraphs:[seed.intro]},{id:'mapa',label:'2. Relacionar',title:'El mapa del tema',paragraphs:['Seguí este recorrido conceptual y explicá qué relación une cada paso. Las flechas ordenan la explicación; no representan necesariamente tuberías ni una secuencia de maniobras.'],flow:seed.flow.split(' > ')}];
 for(const [i,card]of cards.entries())sections.push({id:'concepto-'+i,label:'3. Profundizar · '+(i+1)+'/'+cards.length,title:card.rapida.question,paragraphs:[card.sobrepensada.answer],sources:card.sources.map(source).filter(r=>r.url)});
 sections.push({id:'ejemplo',label:'4. Aplicar',title:'Un ejemplo explicado',paragraphs:[seed.example]});
 for(const [i,card]of diagrams.entries())sections.push({id:'lamina-'+i,label:'5. Reconocer',title:card.visual.title,paragraphs:['Mirá el esquema y recorré sus números. Leé cada nombre junto con su función; después intentá reconstruir la explicación sin mirar la leyenda.'],image:card.visual.url,legend:card.sobrepensada.keyPoints,sources:card.sources.map(source).filter(r=>r.url)});
 sections.push({id:'oral',label:'6. Preparar el oral',title:'Cómo ordenar tu respuesta',paragraphs:['Empezá por la idea central. Desarrollá después las relaciones que aparecen en el mapa y justificá cada una con el funcionamiento o el mecanismo correspondiente. Cerrá con un ejemplo y sus condiciones.'],model:seed.intro,list:cards.map(c=>c.rapida.question),pitfall:seed.pitfall});
 const refs=[...new Map(sections.flatMap(s=>s.sources||[]).map(r=>[r.url,r])).values()];const words=sections.flatMap(s=>[s.title,...s.paragraphs,...(s.legend||[]),s.model||'',...(s.list||[]),s.pitfall||'']).join(' ').split(/\s+/).length;
 return {version:1,subject,unit,name:config.name,topic:config.topics[unit],topics:config.topics,basis:config.basis,sections,sources:refs,minutes:Math.max(3,Math.ceil(words/140)),questionCount:cards.length,practice:cards.map(c=>({id:c.id,question:c.normal.question})),notice:'Desarrollo didáctico propio y referencias de consulta. Complementá los ejemplos con las figuras, convenciones y alcance indicados por tu docente.'}}
module.exports={lesson};
